struct stringx {
    char data[8];
    stringx();
    stringx& operator=(const stringx&);
};

template<class T> struct refptr { T* ptr; };
class hw_texture;
struct vertex_context { char data[16]; };
template<class T> struct my_allocator { };
template<class T, class A> struct vector2 {
    T* begin;
    T* end;
    T* capacity;
    vector2& operator=(const vector2&);
};

struct anim_texture {
    stringx filename;
    vector2<refptr<hw_texture>, my_allocator<refptr<hw_texture> > > textures;
    vector2<vertex_context, my_allocator<vertex_context> > contexts;
    unsigned int flags;
    float frame_time;
    unsigned int frame;
    anim_texture();
    anim_texture& operator=(const anim_texture& rhs) {
        filename = rhs.filename;
        textures = rhs.textures;
        contexts = rhs.contexts;
        flags = rhs.flags;
        frame_time = rhs.frame_time;
        frame = rhs.frame;
        return *this;
    }
    void process_vertex_contexts(unsigned int);
};

struct material {
    stringx material_name;
    stringx texture_filename[4];
    anim_texture maps[4];
    float diffuse_color[4];
    float u_anim;
    float v_anim;
    unsigned int mat_flags;
    material(const material&);
};

material::material(const material& rhs) {
    for (int i = 0; i < 4; ++i) {
        texture_filename[i] = rhs.texture_filename[i];
        maps[i] = rhs.maps[i];
    }
    mat_flags = rhs.mat_flags;
    material_name = rhs.material_name;
    for (int i = 0; i < 4; ++i)
        diffuse_color[i] = rhs.diffuse_color[i];
    u_anim = rhs.u_anim;
    v_anim = rhs.v_anim;
    for (int i = 3; i >= 0; --i)
        if (texture_filename[i].data[4])
            maps[i].process_vertex_contexts(mat_flags);
}
